<?php /** @var \Illuminate\Database\Eloquent\Collection $layaways */ /** @var \Illuminate\Database\Eloquent\Collection $clients */ /** @var \Illuminate\Database\Eloquent\Collection $products */ ?>
<header class="page-head"><div><span class="eyebrow">RESERVAS</span><h1>Apartados</h1><p>Teléfonos retenidos y sus abonos.</p></div><button class="btn btn-primary" onclick="document.querySelector('#new').open=true">+ Apartar teléfono</button></header>
<details class="drawer card" id="new"><summary>Nuevo apartado</summary><form class="panel grid grid-2" method="post" action="./apartados"><div class="field"><label>Cliente</label><select name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as $client): ?><option value="<?= $client->id ?>"><?= htmlspecialchars($client->name) ?></option><?php endforeach ?></select></div><div class="field"><label>Teléfono disponible</label><select name="product_id" required><option value="">Seleccionar</option><?php foreach($products as $product): ?><option value="<?= $product->id ?>"><?= htmlspecialchars($product->name) ?></option><?php endforeach ?></select></div><div class="field"><label>IMEI 1</label><input name="imei1" required></div><div class="field"><label>IMEI 2</label><input name="imei2" required></div><button class="btn btn-primary">Confirmar apartado</button></form></details>
<section class="card table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Teléfono</th><th>IMEI</th><th>Saldo USD</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($layaways as $item): ?><tr><td><?= htmlspecialchars($item->client->name) ?></td><td><strong><?= htmlspecialchars($item->product->name) ?></strong><br><small>$<?= $item->price ?> · Bs. <?= number_format($item->price_ves,2,',','.') ?></small></td><td><small><?= htmlspecialchars($item->imei1) ?><br><?= htmlspecialchars($item->imei2) ?></small></td><td>$<?= $item->getRemainingAmount() ?></td><td><span class="status <?= $item->cancelled_at?'status-danger':($item->getRemainingAmount()>0?'status-warning':'status-success') ?>"><?= $item->cancelled_at?'Cancelado':($item->getRemainingAmount()>0?'Pendiente':'Pagado') ?></span></td><td class="actions"><?php if(!$item->cancelled_at && $item->getRemainingAmount()>0): ?><form method="post" action="./apartados/<?= $item->id ?>/pagar" class="inline-form"><input name="amount" type="number" min="1" max="<?= $item->getRemainingAmount() ?>" required placeholder="USD"><select name="method"><option>Físico</option><option>Punto</option><option>Transferencia</option></select><button class="btn btn-primary btn-sm">Pagar</button></form><?php endif ?><?php if(!$item->cancelled_at): ?><form method="post" action="./apartados/<?= $item->id ?>/cancelar"><button class="btn btn-danger btn-sm" onclick="return confirm('¿Cancelar apartado?')">Cancelar</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
